import re,json,os
ids=[x.strip().lower() for x in open('/app/pdb_ids.txt') if x.strip()]
def fetch(url):
    req=Request(url,headers={'User-Agent':'Mozilla/5.0'})
    return urlopen(req,timeout=30).read().decode()
def parse_fasta(t):
    rec=[]
    h=None;s=[]
    for line in t.splitlines():
        if line.startswith('>'):
            if h is not None: rec.append((h,''.join(s).replace('X','')))
            h=line[1:];s=[]
        else:s.append(re.sub('[^A-Za-z]','',line).upper())
    if h is not None:rec.append((h,''.join(s).replace('X','')))
    return rec
for pid in ids:
    try:
        t=fetch(f'https://www.rcsb.org/fasta/entry/{pid}')
        open(f'/tmp/{pid}.fasta','w').write(t)
        print(pid)
        for h,s in parse_fasta(t): print(' ',len(s),h)
        try:
            m=json.loads(fetch(f'https://data.rcsb.org/rest/v1/core/entry/{pid}'))
            print(' TITLE:',m.get('struct',{}).get('title',''))
        except Exception as e: print(' META_ERROR',e)
    except Exception as e: print(pid,'ERROR',e)
